class HesapMakinesi:
  def topla(self, a, b):
    return a + b

hesap = HesapMakinesi()
print(hesap.topla(5, 10))

class Calisan:
  def __init__(self, isim, maas):
    self.isim = isim
    self.maas = maas

  def zam_yap(self, artis):
    self.maas += artis
    print(f'{self.isim} yeni maaşı: {self.maas}')

c = Calisan('Ali', 5000)
c.zam_yap(1500)

class Araba:
  tekerlek_sayisi = 4

  @classmethod
  def tekerlek_bilgisi(cls):
    print(f'Tüm arabalar {cls.tekerlek_sayisi} tekerleklidir.')

Araba.tekerlek_bilgisi() # Nesne üretmeden sınıf adıyla çağırdık

